def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)
    edge = lambda r, c: r == 0 or r == h - 1 or c == 0 or c == w - 1
    rail = max((v for v in freq if v != bg and any(
        grid[r][c] == v and edge(r, c) for r in range(h) for c in range(w))),
        key=lambda v: freq[v])
    target = min((v for v in freq if v not in (bg, rail)), key=lambda v: freq[v])

    counts = {
        'left': sum(grid[r][0] == rail for r in range(h)),
        'right': sum(grid[r][w-1] == rail for r in range(h)),
        'top': sum(grid[0][c] == rail for c in range(w)),
        'bottom': sum(grid[h-1][c] == rail for c in range(w)),
    }
    if max(counts['left'], counts['right']) >= max(counts['top'], counts['bottom']):
        def runs(side):
            vals = [r for r in range(h) if grid[r][0 if side == 'left' else w-1] == rail]
            groups = []
            for r in vals:
                if not groups or r != groups[-1][-1] + 1:
                    groups.append([r])
                else:
                    groups[-1].append(r)
            return groups
        left_runs, right_runs = runs('left'), runs('right')
        pairs = []
        for lr in left_runs:
            for rr in right_runs:
                if len(lr) == len(rr):
                    pairs.append((lr, rr))
                    break
        for lr, rr in pairs:
            for side_run, opposite_run, side in ((lr, rr, 'left'), (rr, lr, 'right')):
                for i, r in enumerate(side_run):
                    marks = [c for c in range(w) if grid[r][c] == target]
                    if not marks:
                        continue
                    c = marks[0]
                    edge_c = 0 if side == 'left' else w - 1
                    step = 1 if side == 'left' else -1
                    for x in range(edge_c + step, c, step):
                        out[r][x] = target
                    out[r][c] = 4
                    # The paired rail row is activated across its full interior.
                    paired_r = opposite_run[i]
                    for x in range(w):
                        if grid[paired_r][x] != rail:
                            out[paired_r][x] = target
    else:
        # Top/bottom rail segments project inward along columns, stopping at
        # a marker (which is recolored 4); otherwise extend through the interior.
        for c in range(w):
            if grid[0][c] == rail:
                for r in range(1, h):
                    if grid[r][c] == target:
                        out[r][c] = 4
                        break
                    out[r][c] = target
            if grid[h-1][c] == rail:
                for r in range(h-2, -1, -1):
                    if grid[r][c] == target:
                        out[r][c] = 4
                        break
                    out[r][c] = target
    return out
